function money(n){return new Intl.NumberFormat("en-KE",{style:"currency",currency:"KES",maximumFractionDigits:0}).format(n).replace("KES","KSh");}
function productCard(p){const pageUrl=location.href.split("#")[0],dest=p.productPage||`products.html#${p.id}`;const msg=`Hello, I am interested in the ${p.name} listed at ${money(p.price)}. Please confirm the latest price, availability and delivery cost to my location. Page: ${pageUrl}`;return `<article class="product-static-card" id="${p.id}"><img src="${p.image}" width="800" height="600" loading="lazy" decoding="async" alt="${p.name} product illustration"><div class="product-body"><span class="pill">${p.category}</span><h3><a href="${dest}">${p.name}</a></h3>${p.capacity?`<div class="capacity">${p.capacity.toLocaleString()} litres</div>`:""}<div class="price">${money(p.price)}</div><p class="muted">${p.shortDescription}</p><div class="product-actions"><a class="btn btn-outline" href="${dest}">View ${p.capacity?p.capacity.toLocaleString()+"L ":""}details</a><a class="btn btn-whatsapp" target="_blank" rel="noopener" href="${waUrl(msg)}">Get Current Price</a></div></div></article>`;}
function renderProducts(list,target="#productGrid"){const el=document.querySelector(target);if(!el)return;el.innerHTML=list.length?list.map(productCard).join(""):`<div class="info-card" style="grid-column:1/-1"><h3>No products found</h3><p class="muted">Try another product name, category, capacity or price range.</p></div>`;const count=document.querySelector("#resultCount");if(count)count.textContent=`${list.length} products`;}
document.addEventListener("DOMContentLoaded",()=>{const featured=document.querySelector("#featuredProducts");if(featured)renderProducts(PRODUCTS.filter(p=>p.featured).slice(0,8),"#featuredProducts");});